#include <stdio.h>

int main(void) {
    int N, M;
    scanf("%d %d", &N, &M);

    int adj[20] = {0};

    for (int i = 0; i < M; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        x--;
        y--;
        adj[x] |= (1 << y);
        adj[y] |= (1 << x);
    }

    int total = 1 << N;
    int answer = 0;

    for (int mask = 1; mask < total; mask++) {
        int ok = 1;

        for (int i = 0; i < N; i++) {
            if (mask & (1 << i)) {
                if (adj[i] & mask) {
                    ok = 0;
                    break;
                }
            }
        }

        if (ok) {
            answer++;
        }
    }

    printf("%d\n", answer);

    return 0;
}
